document.addEventListener("DOMContentLoaded", function () {
	const termsListItems = document.querySelectorAll("ul.terms-list li");
	termsListItems.forEach((item, index) => {
		if (index <= 0) { return; }

		const previousItem = termsListItems[index - 1];
		const prev = previousItem.getBoundingClientRect().left;
		const curr = () => item.getBoundingClientRect().left;
		const check = () => prev < curr();
		if (check()) {
			const bulletClass = "bullet";
			item.classList.add(bulletClass);
			if (!check()) {
				item.classList.remove(bulletClass);
				previousItem.classList.add("spacing");
			}
			console.log(item, previousItem, curr(), prev);
		}
	});
});
